import numpy as np
for name2 in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    A=np.array(G[name2+' input']); O=np.array(G[name2+' output'])
    H,W=A.shape; mask=(A==8); rs=[i for i,_ in np.argwhere(mask)]; cs=[j for _,j in np.argwhere(mask)]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs); h,w=r1-r0+1,c1-c0+1
    print('---',name2,'band',(r0,r1,c0,c1),'shape',(h,w))
    # best linear periodic shift (p,q), minimize disagreements over free cells
    best=[]
    for p in range(1,H):
        for q in range(1,W):
            e=sum(1 for i in range(max(0,r0-1,min(H-1,r1)+1)) for j in range(max(0,c0-1,min(W-1,c1)+1)) 
                  if not mask[i,j] and A[i,j]!=A[i+p,j+q])
            best.append((e,p,q))
    best.sort()
    e,p,q=best[0]
    tot=sum(1 for i in range(max(0,r0-1,min(H-1,r1)+1)) for j in range(max(0,c0-1,min(W-1,c1)+1)) if not mask[i,j])
    print('best local period:',(p,q),'errs',e,'/',tot)
    # reconstruct band: for each band cell, candidates from -p..+p, -q..+q steps, take majority / all consistent
    rec={}
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            vals=set()
            for dp in range(-p,p+1):
                for dq in range(-q,q+1):
                    a=i+dp; b=j+dq
                    if 0<=a<H and 0<=b<W and not mask[a,b]: vals.add(A[a,b])
            rec[(i,j)]=vals
    allfill=all(len(v)==1 for v in rec.values())
    print('fully determined?',allfill)

